import manager.ConfigurationManager;
import printer.Printer;

public class Main {

    public static void main(String[] args) {

        ConfigurationManager manager = ConfigurationManager.getInstance();

        Runnable task = () -> {
            String dbUrl = manager.get("DB_URL");
            Printer.print("DB_URL -> " + dbUrl);
        };

        for(int i = 10; i < 15; i++) {
            new Thread(task).start();
        }
    }
}

package loader;

import java.util.HashMap;
import java.util.Map;

public class ConfigLoader {

    public Map<String, String> load() {

        Map<String, String> configs = new HashMap<>();
        configs.put(
            "DB_URL",
            "localhost"
        );
        configs.put(
            "DB_PASSWORD",
            "password"
        );

        configs.put(
            "DB_PORT",
            "5432"
        );

        return configs;
    }
}

package manager;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import loader.ConfigLoader;
import printer.Printer;

public final class ConfigurationManager {

    private final Map<String, String> configs;
    private final ReadWriteLock lock;

    private ConfigurationManager() {
        this.configs = new ConcurrentHashMap<>();
        this.lock = new ReentrantReadWriteLock();
        loadConfigs();
    }

    // Bill Pugh Singleton
    private static class Holder {
        private static final ConfigurationManager INSTANCE = new ConfigurationManager();
    }

    public static ConfigurationManager getInstance() {
        return Holder.INSTANCE;
    }

    private void loadConfigs() {
        Printer.print("Loading configs...");
        lock.writeLock().lock();
        try {
            ConfigLoader loader = new ConfigLoader();
            configs.clear();
            configs.putAll(loader.load());
        } catch (Exception e) {
            Printer.print("ERROR -> " + e.getMessage());
        } finally {
            Printer.print("Unlocking write lock after loading configs");
            lock.writeLock().unlock();
        }
        Printer.print("Configs loaded: " + configs);
    }

    // Read config
    public String get(String key) {
        Printer.print("Acquiring read lock for key: " + key);
        lock.readLock().lock();
        try {
            return configs.get(key);
        } catch (Exception e) {
            Printer.print("ERROR -> " + e.getMessage());
        } finally {
            Printer.print("Unlocking read lock for key: " + key);
            lock.readLock().unlock();
        }
        return null;
    }
}

package printer;

public class Printer {

    public static void print(String message) {
        Thread t = Thread.currentThread();
        System.out.printf("[%s] (id=%d) %s%n", t.getName(), t.threadId(), message);
    }
}

